mapper.delete:
delete from t_cruise_plan
where

    plan_id = #{PlanId, jdbcType=BIGINT}

AND

    instance_id = #{instanceId, jdbcType=BIGINT}

mapper.update:
update t_cruise_plan a


a.plan_id = #{PlanId, jdbcType=BIGINT}


a.instance_id = #{instanceId, jdbcType=BIGINT}


a.plan_name = #{PlanName, jdbcType=VARCHAR}


a.point_type = #{PointType, jdbcType=INTEGER}


a.area_id = #{AreaId, jdbcType=VARCHAR}


a.cruise_region_ids = #{CruiseRegionIds, jdbcType=VARCHAR}


a.exception_type = #{ExceptionType, jdbcType=INTEGER}


a.robot_id = #{RobotId, jdbcType=BIGINT}


a.position = #{Position, jdbcType=VARCHAR}


a.algorithm_id = #{AlgorithmId, jdbcType=INTEGER}


a.algorithm_name = #{AlgorithmName, jdbcType=VARCHAR}


a.inferad_analyze = #{InferadAnalyze, jdbcType=VARCHAR}


a.ir_temp_box = #{IrTempBox, jdbcType=VARCHAR}


a.create_time = #{CreateTime, jdbcType=TIMESTAMP}


a.update_time = #{UpdateTime, jdbcType=TIMESTAMP}


where a.plan_id = #{PlanId, jdbcType=BIGINT}

mapper.select:
select
plan_id,
instance_id,
plan_name,
point_type,
area_id,
cruise_region_ids,
exception_type,
robot_id,
position,
algorithm_id,
algorithm_name,
inferad_analyze,
ir_temp_box,
create_time,
update_time
from t_cruise_plan
where 1 = 1

and plan_id = #{PlanId, jdbcType=BIGINT}


and instance_id = #{instanceId, jdbcType=BIGINT}


and plan_name = #{PlanName, jdbcType=VARCHAR}


and point_type = #{PointType, jdbcType=INTEGER}


