and algorithm_name = #{AlgorithmName, jdbcType=VARCHAR}


and inferad_analyze = #{InferadAnalyze, jdbcType=VARCHAR}


and ir_temp_box = #{IrTempBox, jdbcType=VARCHAR}


and create_time = #{CreateTime, jdbcType=TIMESTAMP}


